import fs from'node:fs';import crypto from'node:crypto';
import{loadAnny,loadGNM,json,gunzip}from'./teachers.mjs';
import{NeckSurface}from'./source/neck-baseline/src/NeckSurface.js';
import{CommonPerson}from'./src/CommonPerson.mjs';
export function createCommon(){const c=JSON.parse(new TextDecoder().decode(gunzip('kaopu-unified-human-workbench/assets/canonical.json.gz'))),meta={...json('neck-baseline/assets/kernel.json'),vertexCount:25417},raw=gunzip('neck-baseline/assets/kernel.bin.gz'),kernel=new NeckSurface(meta,raw),files=['src/CommonPerson.mjs','src/State.mjs','source/neck-baseline/src/UnifiedModel.js','source/neck-baseline/src/NeckSurface.js','source/kaopu-anny-workbench/r02/src/AnnyModel.js','source/kaopu-unified-human-workbench/src/GNMModel.js'];const inputs=Object.fromEntries(files.map(p=>[p,crypto.createHash('sha256').update(fs.readFileSync(new URL(p,import.meta.url))).digest('hex')]));inputs.kernel=crypto.createHash('sha256').update(new Uint8Array(raw)).digest('hex');inputs.topology=c.topologySha256;const fingerprint={id:crypto.createHash('sha256').update(JSON.stringify(inputs)).digest('hex'),inputs};return new CommonPerson(loadAnny(),loadGNM(),c,fingerprint,kernel,json('kaopu-mhr-workbench/assets/model.json'));}
